import { Component, computed, input, output } from '@angular/core';
import { TablerIconComponent } from '@tabler/icons-angular';
import { HrmButton } from '../general/hrm-button';
import {
  HRM_WORKFLOW_ACTIONS, HrmWorkflowAction, HrmWorkflowStatus,
} from '../shared/hrm-workflow-status';

/** hrm-workflow-actions — cụm nút hành động CHUẨN cho 1 trạng thái hệ thống (State Machine).
 *  Truyền [status] → tự render đúng các nút chuyển tiếp (Duyệt/Từ chối/Hủy…); bấm phát (action)=key.
 *  Nút dạng icon + text, MÀU theo tông ngữ nghĩa (đỏ/tím/vàng/xanh). Trạng thái kết thúc (Đã hủy)
 *  không có nút. Khoảng cách control ↔ control = --space-2 (rule DS). */
@Component({
  selector: 'hrm-workflow-actions',
  imports: [HrmButton, TablerIconComponent],
  template: `
    @for (a of actions(); track a.key) {
      <hrm-button [variant]="a.tone === 'neutral' ? 'default' : 'primary'" size="md"
        [attr.data-tone]="a.tone" (click)="action.emit(a.key)">
        <tabler-icon [icon]="$any(a.icon)" [size]="15" />
        {{ lang() === 'en' ? a.en : a.vi }}
      </hrm-button>
    }
  `,
  host: { class: 'hrm-workflow-actions' },
  styles: [`
    :host { display: inline-flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
    /* Nút gọn: gap icon↔text nhỏ + padding ngang thu lại (token). */
    hrm-button tabler-icon { margin-right: var(--space-0-5); }
    hrm-button ::ng-deep .ant-btn { padding-inline: var(--space-2); gap: var(--space-0-5); }

    /* Tông màu nút (nền đặc) theo ngữ nghĩa — primary giữ brand xanh; còn lại ép màu tông.
       Ghi đè cả .ant-btn-primary (đặc) để chữ trắng nổi trên nền màu. */
    hrm-button[data-tone='error'] ::ng-deep .ant-btn {
      background: var(--error-base); border-color: var(--error-base); color: var(--static-white, #fff);
    }
    hrm-button[data-tone='error'] ::ng-deep .ant-btn:hover {
      background: var(--error-hover, var(--error-base)); border-color: var(--error-hover, var(--error-base)); filter: brightness(0.95);
    }
    hrm-button[data-tone='warning'] ::ng-deep .ant-btn {
      background: var(--warning-base); border-color: var(--warning-base); color: var(--static-white, #fff);
    }
    hrm-button[data-tone='warning'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
    hrm-button[data-tone='violet'] ::ng-deep .ant-btn {
      background: var(--purple-500); border-color: var(--purple-500); color: var(--static-white, #fff);
    }
    hrm-button[data-tone='violet'] ::ng-deep .ant-btn:hover { filter: brightness(0.95); }
  `],
})
export class HrmWorkflowActions {
  /** Trạng thái hiện tại — quyết định bộ nút hành động. */
  readonly status = input.required<HrmWorkflowStatus>();
  /** Ngôn ngữ nhãn nút (mặc định vi). */
  readonly lang = input<'vi' | 'en'>('vi');
  /** Phát key hành động khi bấm (approve/reject/cancel…). */
  readonly action = output<string>();

  protected readonly actions = computed<HrmWorkflowAction[]>(() => HRM_WORKFLOW_ACTIONS[this.status()] ?? []);
}
